inputs.text:
{
  "question": "What do rules, ADRs and existing code say about reading ledgers and a status feature?"
}

{
  "question": "Does an equivalent exist, and where should status live?"
}

output.text:
{
  "alternatives_considered": [
    {
      "option": "new ledger/status.py",
      "rejected_because": "breaks the 11-file rule in the source folders"
    },
    {
      "option": "only `python -m ledger.reconstruct --latest`",
      "rejected_because": "not the console onboarding interface the task names"
    },
    {
      "option": "argparse subcommand `onboard.py status`",
      "rejected_because": "would change the existing flat CLI and its tests"
    }
  ],
  "assumptions": [
    "the console interface means onboard.py"
  ],
  "decision": "No equivalent exists (reconstruct needs a known run id; nothing finds the latest). Put the logic in ledger/reconstruct.py (existing read-only auditor; no new file in a source folder) and expose it on the console as `python onboard.py --status [--state-dir PATH]`, with --subject no longer required when --status is given.",
  "risks": [
    "mixing --status with run flags needs explicit rejection"
  ],
  "why": "11-file rule forbids a new module in ledger/; app/ may import ledger.reconstruct but not ledger.ledger; onboard.py is the console entry."
}

inputs.text:
{
  "question": "How is the most recent run chosen?"
}

output.text:
{
  "alternatives_considered": [
    {
      "option": "read a run id from approval markers or a new pointer file",
      "rejected_because": "would store new state or read coordinator files; status must write nothing and ledgers are the domains' own evidence"
    },
    {
      "option": "use all event types",
      "rejected_because": "forgeable rejected lines could hijack the answer"
    }
  ],
  "assumptions": [
    "ts from the domains' clocks orders runs; backwards clock is a known stated limit"
  ],
  "decision": "Use only action_executed/refused/failed lines from hash-verified ledgers; latest = max (ts, domain order, seq). token_rejected lines are ignored for this choice. A broken chain is reported, its lines not used.",
  "risks": [
    "an aborted run leaves no ledger line so is never shown; the output says so"
  ],
  "why": "token_rejected lines can be added by anyone with write access (reconstruct LIMITS), so they must not pick the run; unverified chains must not be trusted (ADR-0005/0007 stance)."
}

inputs.text:
{
  "goal": "implement latest_run/format_status and the --status console flag"
}

