inputs.text:
{
  "question": "what do the project rules and code structure require for adding a filter to `experience claims`?"
}

{
  "question": "Where does the filter live: CLI only, or in the shared claims_view?"
}

output.text:
{
  "alternatives_considered": [
    {
      "option": "filter rows in _experience_claims after the view is built",
      "rejected_because": "would leave status_meanings listing statuses no longer shown and duplicate the count logic"
    }
  ],
  "assumptions": [
    "filter applies after the hidden-unverified check, so hidden counts stay about source verification only"
  ],
  "decision": "Filter inside claims_view() via an optional status argument (default None), counting dropped claims in ClaimsView.filtered_out.",
  "risks": [
    "UI could later reuse the argument without surfacing the count"
  ],
  "why": "Rows, hidden count and status meanings are all computed there; filtering in the CLI would leave meanings and JSON inconsistent. The UI shares the function, so the default None keeps its output unchanged."
}

inputs.text:
{
  "question": "How to refuse an unknown status and with which exit code?"
}

output.text:
{
  "alternatives_considered": [
    {
      "option": "validate by hand in _experience_claims and return EXIT_CONFIG_ERROR",
      "rejected_because": "duplicates the status list and the clear message argparse already gives"
    }
  ],
  "assumptions": [
    "EXIT_CONFIG_ERROR=2 and argparse's 2 are the same 'usage error' in the project's docs"
  ],
  "decision": "argparse choices= built from the ClaimStatus enum, so an unknown value prints the valid list and exits 2 (SystemExit), like `task --profile bogus`.",
  "risks": [
    "ClaimStatus is imported when the parser is built (inside the function, not at module top)"
  ],
  "why": "2 is the project's usage-error code and the existing precedent test_an_unknown_profile_is_a_usage_error uses SystemExit(2); choices stay in sync with the enum automatically."
}

inputs.text:
{
  "question": "How must the filter report what it left out, and does the default JSON change?"
}

output.text:
{
  "alternatives_considered": [
    {
      "option": "always emit filtered_out_by_status (0 by default)",
      "rejected_because": "changes default JSON shape"
    }
  ],
  "assumptions": [],
  "decision": "Text prints \"status filter 'X': N claim(s) with another status left out\"; JSON gains status_filter and filtered_out_by_status only when a filter is used. The 'no claims' line is suppressed when filtering so an empty result is not misread as an empty graph.",
  "risks": [
    "consumers must treat the two keys as optional"
  ],
  "why": "Task requires the filter never be silent, and default output must be byte-identical (also the UI's JSON)."
}

